import{z as i,x as B,o,c as p,q as s,j as r,D as t,d as E,s as l,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"自协商与双工","description":"","frontmatter":{"title":"自协商与双工","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/autonegotiation.md","filePath":"cs/autonegotiation.md","lastUpdated":1791063341000}'),d={name:"cs/autonegotiation.md"};function u(C,a,h,c,m,F){const n=B("Mermaid");return o(),p("div",null,[a[2]||(a[2]=s('<h1 id="自协商与双工" tabindex="-1">自协商与双工 <a class="header-anchor" href="#自协商与双工" aria-label="Permalink to &quot;自协商与双工&quot;">​</a></h1><div class="epigraph"><p>链路两端先交换能力页，再选共同的最高模式；半双工与全双工一旦错配，吞吐会塌成冲突与延迟 ACK 的混合物。</p><footer>—— 据 IEEE 802.3 Clause 28 / 73；RFC 4837 对双工不匹配的操作整理</footer></div><p><a href="/cs/ethernet-speeds">上一课</a>列出速率档。两端可能一边强制 100M 半双工、一边自协商。缺口是<strong>自协商</strong>：用脉冲或协商页广告速度、双工、流控；决议选双方都支持的最高优先级。本课不把 PAUSE 帧格式写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>10/100 铜缆用 Fast Link Pulse 传能力。千兆及以上强制自协商（Clause 40/73），否则无法安全启用。决议失败或一边关协商，会出现单工错配：全双工端不听冲突，半双工端不断退避。症状像「网很慢」而不是口 down——比 PCS 丢锁更阴险。</p><p>主干<a href="/cs/csma-switch">CSMA</a> 已说全双工交换链路不用 CD。本课钉的是：如何确认双方都进入全双工。</p><p><span class="marginnote">优先级通常是速度优先，同速则全双工优于半双工。802.3 表是规范；手工强制只在故障排查时用。</span></p><p><span class="marginnote">术语翻译：全双工是「打电话」，两边可以同时说、同时听；半双工是「对讲机」，一次只能一个人讲。半双工靠「先听再说、撞了就退避」的规矩活下去，一旦对面根本不守这套规矩，它就永远在给对方让路。</span></p><h3 id="错配不一定-down" tabindex="-1">错配不一定 down <a class="header-anchor" href="#错配不一定-down" aria-label="Permalink to &quot;错配不一定 down&quot;">​</a></h3><p>双工不一致常表现为「慢」而不是灭灯。千兆以上默认必须协商；一边强制一边 auto 是经典坑。流控能力位只表示可以暂停，不表示已经策略开启。</p><p><span class="marginnote">常见误区：一边设 auto、一边强制 100M 全双工，并不会「协商出」全双工——强制端不发能力页，auto 端探测不到协商方，往往自己回落成半双工，于是口 up、灯亮、却慢到怀疑断网。口诀：要么两边都 auto，要么两边强制成同一档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>过程：并行检测遗留设备 → 交换页 → 选模式 → 训练（千兆以上）→ link up。画两端能力集合的交。错配对照：一端 CRS/碰撞计数飙升。管理上「双方都 auto」优于「一边 auto 一边强制」。</p>',13)),(o(),r(A,null,{default:t(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%B9%BF%E5%91%8A%E8%83%BD%E5%8A%9B%E9%A1%B5%22%5D%20--%3E%20INT%5B%22%E5%8F%96%E4%BA%A4%E9%9B%86%22%5D%0A%20%20INT%20--%3E%20PRI%5B%22%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%E5%86%B3%E8%AE%AE%22%5D%0A%20%20PRI%20--%3E%20TRN%5B%22%E5%8F%AF%E9%80%89%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRN%20--%3E%20UP%5B%22link%20up%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("自协商在 PHY，不经过"),e("a",{href:"/cs/spanning-tree"},"生成树"),E(" 的 BPDU。口 up 之后 STP 才开始。流控能力位会带到下一课 PAUSE/PFC：协商成功只表示「可以发暂停」，策略仍由交换机配置。")],-1)),a[5]||(a[5]=e("p",null,"与 IP 无关：协商失败不会发 ICMP，只会让该口不成链路。",-1)),(o(),r(A,null,{default:t(()=>[l(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%85%A8%E5%8F%8C%E5%B7%A5%E7%AB%AF%3A%20%E6%83%B3%E5%8F%91%E5%B0%B1%E5%8F%91%2C%20%E4%B8%8D%E5%90%AC%E5%86%B2%E7%AA%81%22%5D%20--%3E%20L%5B%22%E9%93%BE%E8%B7%AF%E4%B8%8A%E4%B8%A4%E4%B8%AA%E5%8F%91%E9%80%81%E6%96%B9%E5%90%91%E6%92%9E%E5%9C%A8%E4%B8%80%E8%B5%B7%22%5D%0A%20%20H%5B%22%E5%8D%8A%E5%8F%8C%E5%B7%A5%E7%AB%AF%3A%20%E5%85%88%E5%90%AC%E5%86%8D%E5%8F%91%2C%20%E6%92%9E%E4%BA%86%E5%B0%B1%E9%80%80%E9%81%BF%22%5D%20--%3E%20L%0A%20%20L%20--%3E%20X%5B%22%E5%8D%8A%E5%8F%8C%E5%B7%A5%E7%AB%AF%E5%88%A4%E4%B8%BA%E7%A2%B0%E6%92%9E%2C%20%E6%8C%87%E6%95%B0%E9%80%80%E9%81%BF%E9%87%8D%E4%BC%A0%22%5D%0A%20%20L%20--%3E%20Y%5B%22%E5%85%A8%E5%8F%8C%E5%B7%A5%E7%AB%AF%E6%AF%AB%E6%97%A0%E5%AF%9F%E8%A7%89%2C%20%E7%BB%A7%E7%BB%AD%E7%81%8C%E5%B8%A7%22%5D%0A%20%20X%20--%3E%20Z%5B%22%E7%A2%B0%E6%92%9E%E8%AE%A1%E6%95%B0%E9%A3%99%E5%8D%87%2C%20%E5%90%9E%E5%90%90%E5%A1%8C%E9%99%B7%22%5D%0A%20%20Y%20--%3E%20Z%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：半双工端第 \\(n\\) 次碰撞后在 \\(0\\) 到 \\(2^{n}-1\\) 个时隙里抽签等待，撞得越多等得越久；错配时它几乎每帧都「撞」，重传与退避吃掉绝大部分时间，实际吞吐可能只剩个位数百分比——而对端各计数器全绿，看起来一切正常。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Backplane 协商的全部 FEC 能力位。PAUSE 与 PFC 是下一课。后课默认：双工与速率由自协商决议；错配表现为性能故障而非必然 down。</p><p>不要在汇聚核心关自协商「为了稳定」——当代光口另有协商，强制更容易错。</p><p>下一课<a href="/cs/pause-pfc">PAUSE 与 PFC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>能力页取交，再按标准优先级选模式。</li><li>双工错配不总让口 down，但会毁掉吞吐。</li><li>千兆以上默认必须协商。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3 Clause 28/73；运维对照 RFC 4837。</li></ul>',7))])}const f=i(d,[["render",u]]);export{D as __pageData,f as default};
